import clsx from 'clsx'
import React from 'react'
import type { PropsWithChildren } from 'react'
import { Cancel, CheckCircleOutline } from '../icons'

function Guideline({
  children,
}: PropsWithChildren<Record<string, never>>): JSX.Element {
  return <div className="flex space-x-4">{children}</div>
}

interface DirectiveProps {
  type: DirectiveType
}
enum DirectiveType {
  'do' = 'Do',
  'dont' = "Don't",
}

function Directive({
  children,
  type = DirectiveType['do'],
}: PropsWithChildren<DirectiveProps>): JSX.Element {
  return (
    <div
      className={clsx(
        'border-l-3 w-1/2',
        type === DirectiveType['do']
          ? 'border-success-main text-success-main'
          : 'border-error-main text-error-main',
      )}
    >
      <div className="flex items-center">
        <span className="w-5 h-5 flex">
          {type === DirectiveType['do'] ? <CheckCircleOutline /> : <Cancel />}
        </span>
        <div className="inline pl-1">{type}</div>
      </div>
      <div
        className={clsx(
          'border-l-4 rounded-l',
          type === DirectiveType['do']
            ? 'border-success-light'
            : 'border-error-light',
        )}
      >
        {children}
      </div>
    </div>
  )
}

function Do({
  children,
}: PropsWithChildren<Record<string, never>>): JSX.Element {
  return <Directive type={DirectiveType['do']}>{children}</Directive>
}

function Dont({
  children,
}: PropsWithChildren<Record<string, never>>): JSX.Element {
  return <Directive type={DirectiveType['dont']}>{children}</Directive>
}

Guideline.Do = Do
Guideline.Dont = Dont

export default Guideline
